export async function bakeMesh({
  inputPath = DEFAULT_INPUT,
  assetPath = DEFAULT_ASSET,
  reportPath = DEFAULT_REPORT,
  quiet = false,
} = {}) {
  const inputBytes = await readFile(inputPath);
  const inputHash = sha256(inputBytes);
